function syncProfileMode(){
  if(sharedContext)sharedFlow.syncRoute();
  let isProfile = location.hash === '#perfil-medico';
  if(sharedContext&&!doctorAccountCurrent()){document.body.classList.toggle('profile-mode',isProfile);staleDoctorProfile();sharedFlow.showError(Error('La sesión o el expediente cambió. Vuelve a abrirlo desde tu acceso.'));document.querySelectorAll('.form-grid input,.form-grid select,.form-grid button').forEach(control=>{control.disabled=true;});return;}
  if(isProfile && (!doctorAccountCurrent() || !getState().profile?.email)&&!sharedContext){window.location.href='registro-doctor.html';isProfile=false;}
  else if(isProfile&&!sharedContext&&doctorStorage.getItem('pulzzo_doctor_verified')!=='true'){window.location.href='verificacion-doctor.html';isProfile=false;}
  else if(isProfile&&sharedContext&&!sharedContext.isAssistant&&!sharedContext.isVerified){sharedFlow.showError(Error('Verifica el acceso como titular para continuar.'));isProfile=false;}
  document.body.classList.toggle('profile-mode', isProfile);
  if(isProfile){document.title='Perfil médico | Pulzzo';renderProfile();window.scrollTo(0,0);}else{document.title=sharedContext?'Completar registro médico | Pulzzo':'Regístrate como doctor o clínica | Pulzzo';if(sharedContext)window.scrollTo(0,0);}
}
window.addEventListener('hashchange',()=>{++profilePhotoReadVersion;closeProfilePhotoCamera();syncProfileMode();});

